#include <stdio.h>
#include "sheen/demux.h"
int main(int argc,char **argv){if(argc!=2){fprintf(stderr,"usage: %s SOURCE\\n",argv[0]);return 2;}sheen_demux_result r;int rc=sheen_demux_mpegts_file(argv[1],&r);if(rc){fprintf(stderr,"demux failed: %d\\n",rc);return 1;}printf("{\"source\":\"%s\",\"container\":\"%s\",\"programs\":[",r.source,r.container);for(size_t i=0;i<r.program_count;i++){if(i)putchar(',');sheen_demux_program *p=&r.programs[i];printf("{\"program_number\":%u,\"pmt_pid\":%u,\"pcr_pid\":%u,\"streams\":[",p->program_number,p->pmt_pid,p->pcr_pid);for(size_t j=0;j<p->stream_count;j++){if(j)putchar(',');printf("{\"pid\":%u,\"stream_type\":%u,\"index\":%u}",p->streams[j].pid,p->streams[j].stream_type,p->streams[j].stream_index);}printf("]}");}printf("]}\n");return 0;}
